import Delta from 'quill-delta';
import { Registry, Scope, Attributor, ClassAttributor, StyleAttributor } from 'parchment';
import { describe, expect, test } from 'vitest';
import Quill from '../../../src/core';
import { Block } from '../../../src/blots/block';
import Break from '../../../src/blots/break';
import Cursor from '../../../src/blots/cursor';
import Inline from '../../../src/blots/inline';
import TextBlot from '../../../src/blots/text';
import { ListContainer, ListItem } from '../../../src/formats/list';
import CodeBlock from '../../../src/formats/code';
import Bold from '../../../src/formats/bold';
import Italic from '../../../src/formats/italic';
import Strike from '../../../src/formats/strike';

// Direction attributors
const DirectionAttribute = new Attributor('direction', 'dir', { scope: Scope.BLOCK, whitelist: ['rtl'] });
const DirectionStyle = new StyleAttributor('direction', 'direction', { scope: Scope.BLOCK, whitelist: ['rtl'] });

// Color attributors  
const ColorClass = new ClassAttributor('color', 'ql-color', { scope: Scope.INLINE });
const ColorStyle = new StyleAttributor('color', 'color', { scope: Scope.INLINE });

// Helper to create a minimal registry with specific additional formats
const createRegistry = (formats: Attributor[] = []) => {
  const registry = new Registry();
  registry.register(Block);
  registry.register(Break);
  registry.register(Cursor);
  registry.register(Inline);
  registry.register(Scroll as any);
  registry.register(TextBlot);
  registry.register(ListContainer);
  registry.register(ListItem);
  formats.forEach(f => registry.register(f));
  return registry;
};

// Import Scroll type
import Scroll from '../../../src/blots/scroll';

describe('Clipboard format filtering - unsupported formats dropped', () => {
  test('code-block: without format registered, <pre> produces plain text (no trailing newline)', () => {
    const container = document.body.appendChild(document.createElement('div'));
    const registry = createRegistry(); // No code-block
    const quill = new Quill(container, { registry });
    const delta = quill.clipboard.convert({ html: '<pre> 01 \n 23 </pre>' });
    // Whitespace kept, no trailing newline, no code-block format
    expect(delta).toEqual(new Delta().insert(' 01 \n 23 '));
  });

  test('code-block: with format registered, <pre> produces code-block:true', () => {
    const container = document.body.appendChild(document.createElement('div'));
    const registry = createRegistry([CodeBlock as any]);
    const quill = new Quill(container, { registry });
    const delta = quill.clipboard.convert({ html: '<pre> 01 \n 23 </pre>' });
    expect(delta).toEqual(new Delta().insert(' 01 \n 23 \n', { 'code-block': true }));
  });

  test('direction: without attributor, <p style="direction:rtl;"> produces plain text', () => {
    const container = document.body.appendChild(document.createElement('div'));
    const registry = createRegistry(); // No direction
    const quill = new Quill(container, { registry });
    const delta = quill.clipboard.convert({ html: '<p style="direction:rtl;">Test</p>' });
    expect(delta).toEqual(new Delta().insert('Test'));
  });

  test('direction: with attributor, <p style="direction:rtl;"> produces direction:rtl', () => {
    const container = document.body.appendChild(document.createElement('div'));
    const registry = createRegistry([DirectionStyle]);
    const quill = new Quill(container, { registry });
    const delta = quill.clipboard.convert({ html: '<p style="direction:rtl;">Test</p>' });
    expect(delta).toEqual(new Delta().insert('Test\n', { direction: 'rtl' }));
  });

  test('color: without attributor, nested style colors produce plain text', () => {
    const container = document.body.appendChild(document.createElement('div'));
    const registry = createRegistry(); // No color
    const quill = new Quill(container, { registry });
    const delta = quill.clipboard.convert({ html: '<span style="color: red;"><span style="color: blue;">Test</span></span>' });
    expect(delta).toEqual(new Delta().insert('Test'));
  });

  test('color: with attributor, nested style colors produces color:blue', () => {
    const container = document.body.appendChild(document.createElement('div'));
    const registry = createRegistry([ColorStyle]);
    const quill = new Quill(container, { registry });
    const delta = quill.clipboard.convert({ html: '<span style="color: red;"><span style="color: blue;">Test</span></span>' });
    expect(delta).toEqual(new Delta().insert('Test', { color: 'blue' }));
  });

  test('b/i/strike: without formats, <b>/<i>/<strike> produce plain text', () => {
    const container = document.body.appendChild(document.createElement('div'));
    const registry = createRegistry(); // No Bold/Italic/Strike
    const quill = new Quill(container, { registry });
    const delta = quill.clipboard.convert({ html: '<b>Bold</b><i>Italic</i><strike>Strikethrough</strike>' });
    expect(delta).toEqual(new Delta().insert('BoldItalicStrikethrough'));
  });

  test('b/i/strike: with formats, <b>/<i>/<strike> produce bold/italic/strike', () => {
    const container = document.body.appendChild(document.createElement('div'));
    const registry = createRegistry([Bold, Italic, Strike]);
    const quill = new Quill(container, { registry });
    const delta = quill.clipboard.convert({ html: '<b>Bold</b><i>Italic</i><strike>Strikethrough</strike>' });
    expect(delta).toEqual(
      new Delta()
        .insert('Bold', { bold: true })
        .insert('Italic', { italic: true })
        .insert('Strikethrough', { strike: true })
    );
  });
});
